def norm_boolish(v) -> str:
    if v is True or v == "true" or v == "Yes":
        return "Yes"
    if v is False or v == "false" or v == "No":
        return "No"
    if v in (None, "", "null"):
        return "Unknown"
    return str(v)


def social_to_str(v) -> str:
    if v is None or v == "Unknown" or v == "":
        return "Unknown"
    if isinstance(v, dict):
        parts = []
        for k, val in v.items():
            if val:
                parts.append(f"{k} {val}" if not str(val).startswith("@") else f"{k} {val}")
        return "; ".join(parts) if parts else "Unknown"
    return str(v)


def revenue_to_str(v) -> str:
    if v is None or v == "" or v == "null":
        return "Unknown"
    if isinstance(v, (int, float)):
        return f"£{v:,.0f}" if v >= 1000 else str(v)
    return str(v)


def to_row(obj: dict, confidence: str = "medium") -> dict:
    return {
        "name": obj["name"],
        "website": obj.get("website") or "Unknown",
        "category": obj.get("category") or "Unknown",
        "country": obj.get("country") or "Unknown",
        "founded": str(obj.get("founded") or "Unknown"),
        "linkedin_employees": str(obj.get("linkedInEmployees") or obj.get("linkedin_employees") or "Unknown"),
        "ships_international": norm_boolish(obj.get("shipsInternational", obj.get("ships_international"))),
        "hires_remotely": norm_boolish(obj.get("hiresRemote", obj.get("hires_remotely"))),
        "hiring_manager_on_linkedin": norm_boolish(
            obj.get("hiringManagerOnLinkedIn", obj.get("hiring_manager_on_linkedin"))
        ),
        "recent_job_postings": str(obj.get("recentJobPostings") or obj.get("recent_job_postings") or "Unknown"),
        "careers_page": str(obj.get("careersPage") or obj.get("careers_page") or "Unknown"),
        "social_media": social_to_str(obj.get("socialMedia", obj.get("social_media"))),
        "revenue_last_fy": revenue_to_str(obj.get("revenueLastFY", obj.get("revenue_last_fy"))),
        "legitimacy_notes": str(obj.get("legitimacyNotes") or obj.get("legitimacy_notes") or "Unknown"),
        "meets_strict_criteria": norm_boolish(obj.get("meetsStrictCriteria", obj.get("meets_strict_criteria"))),
        "data_confidence": confidence,
    }


def main() -> None:
    existing = list(csv.DictReader(OUT.open(encoding="utf-8")))
    seen = {r["name"].strip().lower() for r in existing}
    # also see by website host roughly
    seen_sites = {r["website"].strip().lower().rstrip("/") for r in existing}

    added = 0
    for batch, conf in ((json.loads(EU_JSON), "medium"), (json.loads(UK_BEAUTY_SHOES), "medium")):
        for obj in batch:
            key = obj["name"].strip().lower()
            site = (obj.get("website") or "").strip().lower().rstrip("/")
            if key in seen or (site and site in seen_sites):
                continue
            existing.append(to_row(obj, conf))
            seen.add(key)
            if site:
                seen_sites.add(site)
            added += 1

    # Enrich REFY revenue if present
    for r in existing:
        if r["name"].strip().lower() == "refy beauty" or r["name"].strip().lower() == "refy":
            if "40" not in r["revenue_last_fy"]:
                r["revenue_last_fy"] = "~£40.4m (Fast Track reported)"
                r["legitimacy_notes"] = (
                    r["legitimacy_notes"] + "; Fast Track ~£40.4m sales reported"
                    if r["legitimacy_notes"] != "Unknown"
                    else "Fast Track ~£40.4m sales reported"
                )

    with OUT.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=FIELDS)
        w.writeheader()
        w.writerows(existing)

    print(f"Added {added} new companies. Total now {len(existing)} -> {OUT}")


if __name__ == "__main__":
    main()
